package com.timeline;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLuancher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TimelinePlugin.class);
		RuneLite.main(args);
	}
}

package com.timeline;

import com.google.inject.Provides;
import com.timeline.playback.TimelinePathOverlay;
import com.timeline.playback.TimelinePlaybackController;
import com.timeline.record.TimelineRecorder;
import com.timeline.ui.TimelinePanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Timeline",
	description = "Records where you've traveled and plays it back on the world map",
	tags = {"maps", "data"}
)
public class TimelinePlugin extends Plugin
{
	private static final String CONFIG_GROUP = "timeline";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TimelineRecorder recorder;

	@Inject
	private TimelinePlaybackController playbackController;

	@Inject
	private TimelinePathOverlay pathOverlay;

	@Inject
	private TimelinePanel panel;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		recorder.startUp();
		overlayManager.add(pathOverlay);

		BufferedImage icon = ImageUtil.loadImageResource(TimelinePlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Timeline")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(pathOverlay);
		panel.shutDown();
		playbackController.shutDown();
		recorder.shutDown();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		recorder.onGameTick();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		recorder.onGameStateChanged(event.getGameState());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("liveTracking".equals(event.getKey()))
		{
			panel.setLiveTrackingSelected(Boolean.parseBoolean(event.getNewValue()));
		}
		else if ("followPlayback".equals(event.getKey()))
		{
			panel.setFollowPlaybackSelected(Boolean.parseBoolean(event.getNewValue()));
		}
	}

	@Provides
	TimelineConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TimelineConfig.class);
	}
}

package com.timeline.playback;

import com.timeline.TimelineConfig;
import com.timeline.data.TimelinePoint;
import com.timeline.record.TimelineRecorder;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

/**
 * Draws recorded timeline paths on the world map: historical playback (from
 * {@link TimelinePlaybackController}) and/or the current in-progress session's live trail.
 * Mimics {@link WorldMapOverlay}'s own MANUAL/drawAfterInterface setup so render() is only
 * invoked while the map widget is actually drawing.
 */
public class TimelinePathOverlay extends Overlay
{
	private static final int MARKER_RADIUS = 4;
	private static final int UPCOMING_ALPHA = 90;

	/**
	 * How close the last point of one session has to be to the first point of the next (same
	 * plane) to draw a connecting line between them - e.g. a brief disconnect/relog in place -
	 * instead of leaving that boundary unconnected the way a genuine gap should stay. This is a
	 * purely visual connector: it doesn't affect playback timing, the marker still jumps across it
	 * instantly, same as any other segment boundary.
	 */
	private static final int CONNECTED_SESSION_DISTANCE_TILES = 100;

	private final Client client;
	private final TimelineConfig config;
	private final TimelinePlaybackController playbackController;
	private final TimelineRecorder recorder;
	private final WorldMapOverlay worldMapOverlay;

	@Inject
	private TimelinePathOverlay(
		Client client,
		TimelineConfig config,
		TimelinePlaybackController playbackController,
		TimelineRecorder recorder,
		WorldMapOverlay worldMapOverlay)
	{
		this.client = client;
		this.config = config;
		this.playbackController = playbackController;
		this.recorder = recorder;
		this.worldMapOverlay = worldMapOverlay;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<List<TimelinePoint>> segments = playbackController.getSegments();
		List<TimelinePoint> liveTrail = config.liveTracking() ? recorder.getCurrentSessionPoints() : Collections.emptyList();

		if (segments.isEmpty() && liveTrail.size() < 2)
		{
			return null;
		}

		Widget mapWidget = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (mapWidget == null || mapWidget.isHidden())
		{
			return null;
		}

		Shape originalClip = graphics.getClip();
		Stroke originalStroke = graphics.getStroke();
		graphics.setClip(mapWidget.getBounds());
		graphics.setStroke(new BasicStroke(config.lineThickness(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		try
		{
			if (!segments.isEmpty())
			{
				drawPlayback(graphics, segments);
			}

			if (liveTrail.size() >= 2)
			{
				drawLiveTrail(graphics, liveTrail);
			}
		}
		finally
		{
			graphics.setClip(originalClip);
			graphics.setStroke(originalStroke);
		}

		return null;
	}

	private void drawPlayback(Graphics2D graphics, List<List<TimelinePoint>> segments)
	{
		Color pathColor = config.pathColor();
		Color teleportColor = config.teleportColor();
		Color upcomingPathColor = withAlpha(pathColor, UPCOMING_ALPHA);
		Color upcomingTeleportColor = withAlpha(teleportColor, UPCOMING_ALPHA);

		int currentSegment = playbackController.getCurrentSegmentIndex();
		int currentIndex = playbackController.getCurrentIndexInSegment();

		for (int segIndex = 0; segIndex < segments.size(); segIndex++)
		{
			List<TimelinePoint> segment = segments.get(segIndex);
			for (int i = 0; i < segment.size() - 1; i++)
			{
				TimelinePoint from = segment.get(i);
				TimelinePoint to = segment.get(i + 1);
				boolean played = segIndex < currentSegment || (segIndex == currentSegment && i < currentIndex);
				boolean teleport = to.isTeleport();

				Color color;
				if (teleport)
				{
					color = played ? teleportColor : upcomingTeleportColor;
				}
				else
				{
					color = played ? pathColor : upcomingPathColor;
				}

				drawSegmentLine(graphics, from, to, color);
			}

			if (segIndex < segments.size() - 1)
			{
				drawSessionBridge(graphics, segment, segments.get(segIndex + 1), segIndex < currentSegment, pathColor, upcomingPathColor);
			}
		}

		WorldPoint current = playbackController.getInterpolatedPosition();
		if (current != null)
		{
			net.runelite.api.Point marker = worldMapOverlay.mapWorldPointToGraphicsPoint(current);
			if (marker != null)
			{
				graphics.setColor(pathColor);
				graphics.fillOval(marker.getX() - MARKER_RADIUS, marker.getY() - MARKER_RADIUS, MARKER_RADIUS * 2, MARKER_RADIUS * 2);
			}
		}
	}

	/**
	 * Draws a connecting line bridging two consecutive sessions when the position didn't really
	 * change between them (e.g. a brief disconnect/relog), instead of leaving that boundary
	 * unconnected the way a genuine gap between unrelated sessions should stay.
	 */
	private void drawSessionBridge(Graphics2D graphics, List<TimelinePoint> segment, List<TimelinePoint> nextSegment, boolean played, Color pathColor, Color upcomingPathColor)
	{
		if (segment.isEmpty() || nextSegment.isEmpty())
		{
			return;
		}

		TimelinePoint lastOfSegment = segment.get(segment.size() - 1);
		TimelinePoint firstOfNext = nextSegment.get(0);
		if (!areSessionsConnected(lastOfSegment, firstOfNext))
		{
			return;
		}

		drawSegmentLine(graphics, lastOfSegment, firstOfNext, played ? pathColor : upcomingPathColor);
	}

	private static boolean areSessionsConnected(TimelinePoint lastOfSegment, TimelinePoint firstOfNext)
	{
		if (lastOfSegment.getPlane() != firstOfNext.getPlane())
		{
			return false;
		}

		int distance = Math.max(Math.abs(firstOfNext.getX() - lastOfSegment.getX()), Math.abs(firstOfNext.getY() - lastOfSegment.getY()));
		return distance <= CONNECTED_SESSION_DISTANCE_TILES;
	}

	private void drawLiveTrail(Graphics2D graphics, List<TimelinePoint> points)
	{
		Color pathColor = config.pathColor();
		Color teleportColor = config.teleportColor();

		for (int i = 0; i < points.size() - 1; i++)
		{
			TimelinePoint from = points.get(i);
			TimelinePoint to = points.get(i + 1);
			Color color = to.isTeleport() ? teleportColor : pathColor;
			drawSegmentLine(graphics, from, to, color);
		}
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private void drawSegmentLine(Graphics2D graphics, TimelinePoint from, TimelinePoint to, Color color)
	{
		net.runelite.api.Point a = worldMapOverlay.mapWorldPointToGraphicsPoint(worldPointOf(from));
		net.runelite.api.Point b = worldMapOverlay.mapWorldPointToGraphicsPoint(worldPointOf(to));
		if (a == null || b == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}

	private static WorldPoint worldPointOf(TimelinePoint point)
	{
		return new WorldPoint(point.getX(), point.getY(), point.getPlane());
	}
}

package com.timeline.playback;

import com.timeline.data.TimelinePoint;
import com.timeline.data.TimelineSessionMeta;
import com.timeline.data.TimelineSessionStore;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * Drives playback of one or more recorded sessions ("segments") drawn/animated on the world map.
 * A single session is just the one-segment case; "all sessions" loads every session as its own
 * segment. Time spent logged out between sessions is never part of the playback timeline - the
 * marker jumps instantly from the end of one segment to the start of the next.
 */
@Singleton
public class TimelinePlaybackController
{
	private static final int TIMER_INTERVAL_MS = 50;

	private static final LoadedTimeline EMPTY = new LoadedTimeline(Collections.emptyList(), new long[0], 0);

	private final TimelineSessionStore store;
	private final Client client;
	private final ClientThread clientThread;
	private final ExecutorService loadExecutor = Executors.newSingleThreadExecutor();
	private final Timer timer;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private volatile LoadedTimeline timeline = EMPTY;
	private volatile boolean playing;
	private volatile long currentTimeMs;
	private volatile double speedMultiplier = 1.0;
	private volatile boolean loop;
	private volatile boolean followPlayback;

	// Only ever touched from tick(), which always runs on the EDT via the Swing Timer.
	private WorldPoint lastFollowedPoint;

	@Inject
	TimelinePlaybackController(TimelineSessionStore store, Client client, ClientThread clientThread)
	{
		this.store = store;
		this.client = client;
		this.clientThread = clientThread;
		this.timer = new Timer(TIMER_INTERVAL_MS, e -> tick());
	}

	public void shutDown()
	{
		timer.stop();
		loadExecutor.shutdownNow();
	}

	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public void loadSession(TimelineSessionMeta meta)
	{
		loadSegments(Collections.singletonList(meta), true);
	}

	public void loadAllSessions(List<TimelineSessionMeta> metas)
	{
		loadAllSessions(metas, true);
	}

	/**
	 * @param panToStart whether to pan the world map to the loaded timeline's start location.
	 * Used to suppress the jump for the catch-all "All Sessions" entry, which can span locations
	 * far apart across a player's whole history rather than one deliberately chosen spot.
	 */
	public void loadAllSessions(List<TimelineSessionMeta> metas, boolean panToStart)
	{
		List<TimelineSessionMeta> sorted = new ArrayList<>(metas);
		sorted.sort(Comparator.comparingLong(TimelineSessionMeta::getStartTime));
		loadSegments(sorted, panToStart);
	}

	private void loadSegments(List<TimelineSessionMeta> metas, boolean panToStart)
	{
		pause();
		loadExecutor.execute(() ->
		{
			List<List<TimelinePoint>> loaded = new ArrayList<>();
			for (TimelineSessionMeta meta : metas)
			{
				List<TimelinePoint> points = store.loadPoints(meta.getId());
				if (!points.isEmpty())
				{
					loaded.add(points);
				}
			}
			applyTimeline(buildTimeline(loaded), panToStart);
		});
	}

	private static LoadedTimeline buildTimeline(List<List<TimelinePoint>> segments)
	{
		long[] offsets = new long[segments.size()];
		long cursor = 0;
		for (int i = 0; i < segments.size(); i++)
		{
			offsets[i] = cursor;
			List<TimelinePoint> segment = segments.get(i);
			long duration = segment.size() > 1
				? segment.get(segment.size() - 1).getTimestamp() - segment.get(0).getTimestamp()
				: 0;
			cursor += duration;
		}
		return new LoadedTimeline(segments, offsets, cursor);
	}

	private void applyTimeline(LoadedTimeline newTimeline, boolean panToStart)
	{
		timeline = newTimeline;
		currentTimeMs = 0;
		playing = false;
		timer.stop();
		lastFollowedPoint = null;
		notifyListeners();
		if (panToStart)
		{
			panMapToStart(newTimeline);
		}
	}

	private void panMapToStart(LoadedTimeline newTimeline)
	{
		if (newTimeline.segments.isEmpty() || newTimeline.segments.get(0).isEmpty())
		{
			return;
		}

		WorldPoint start = worldPointOf(newTimeline.segments.get(0).get(0));
		clientThread.invoke(() -> client.getWorldMap().setWorldMapPositionTarget(start));
	}

	public void play()
	{
		if (timeline.totalDurationMs <= 0)
		{
			return;
		}

		if (currentTimeMs >= timeline.totalDurationMs)
		{
			currentTimeMs = 0;
		}

		playing = true;
		timer.start();
		notifyListeners();
	}

	public void pause()
	{
		playing = false;
		timer.stop();
		notifyListeners();
	}

	public void seekTo(long timeMs)
	{
		currentTimeMs = clamp(timeMs, 0, timeline.totalDurationMs);
		notifyListeners();
	}

	/**
	 * Pauses and seeks in one step. Calling {@link #pause()} then {@link #seekTo(long)} separately
	 * is unsafe from a UI listener: pause()'s own notification reentrantly resyncs the scrubber to
	 * the pre-seek position before the caller gets a chance to read the drag target, silently
	 * discarding the seek. Combining both into a single state change/notification avoids that.
	 */
	public void pauseAndSeekTo(long timeMs)
	{
		playing = false;
		timer.stop();
		currentTimeMs = clamp(timeMs, 0, timeline.totalDurationMs);
		notifyListeners();
	}

	public void setSpeed(double speed)
	{
		speedMultiplier = speed;
	}

	public void setLoop(boolean loop)
	{
		this.loop = loop;
	}

	public boolean isLoop()
	{
		return loop;
	}

	public void setFollowPlayback(boolean followPlayback)
	{
		this.followPlayback = followPlayback;
	}

	public boolean isFollowPlayback()
	{
		return followPlayback;
	}

	public boolean isPlaying()
	{
		return playing;
	}

	public long getCurrentTimeMs()
	{
		return currentTimeMs;
	}

	public long getTotalDurationMs()
	{
		return timeline.totalDurationMs;
	}

	public double getSpeedMultiplier()
	{
		return speedMultiplier;
	}

	public List<List<TimelinePoint>> getSegments()
	{
		return timeline.segments;
	}

	public int getCurrentSegmentIndex()
	{
		return resolveSegmentIndex(timeline, currentTimeMs);
	}

	public int getCurrentIndexInSegment()
	{
		LoadedTimeline t = timeline;
		int segIndex = resolveSegmentIndex(t, currentTimeMs);
		if (segIndex < 0)
		{
			return -1;
		}

		List<TimelinePoint> segment = t.segments.get(segIndex);
		long localTs = segment.get(0).getTimestamp() + (currentTimeMs - t.segmentStartOffsets[segIndex]);
		return bracketBefore(segment, localTs);
	}

	public WorldPoint getInterpolatedPosition()
	{
		LoadedTimeline t = timeline;
		int segIndex = resolveSegmentIndex(t, currentTimeMs);
		if (segIndex < 0)
		{
			return null;
		}

		List<TimelinePoint> segment = t.segments.get(segIndex);
		long localTs = segment.get(0).getTimestamp() + (currentTimeMs - t.segmentStartOffsets[segIndex]);
		return interpolate(segment, localTs);
	}

	private void tick()
	{
		LoadedTimeline t = timeline;
		if (t.totalDurationMs <= 0)
		{
			pause();
			return;
		}

		long next = currentTimeMs + (long) (TIMER_INTERVAL_MS * speedMultiplier);
		if (next >= t.totalDurationMs)
		{
			if (loop)
			{
				currentTimeMs = next % t.totalDurationMs;
			}
			else
			{
				currentTimeMs = t.totalDurationMs;
				pause();
			}
		}
		else
		{
			currentTimeMs = next;
		}
		followMapIfEnabled();
		notifyListeners();
	}

	private void followMapIfEnabled()
	{
		if (!followPlayback)
		{
			return;
		}

		WorldPoint current = getInterpolatedPosition();
		if (current == null || current.equals(lastFollowedPoint))
		{
			return;
		}

		lastFollowedPoint = current;
		clientThread.invoke(() -> client.getWorldMap().setWorldMapPositionTarget(current));
	}

	private void notifyListeners()
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			for (Runnable listener : listeners)
			{
				listener.run();
			}
		}
		else
		{
			SwingUtilities.invokeLater(this::notifyListeners);
		}
	}

	private static int resolveSegmentIndex(LoadedTimeline t, long timeMs)
	{
		for (int i = t.segments.size() - 1; i >= 0; i--)
		{
			if (timeMs >= t.segmentStartOffsets[i])
			{
				return i;
			}
		}
		return t.segments.isEmpty() ? -1 : 0;
	}

	/**
	 * Index of the last point at or before {@code targetTs} within the segment.
	 */
	private static int bracketBefore(List<TimelinePoint> segment, long targetTs)
	{
		if (targetTs <= segment.get(0).getTimestamp())
		{
			return 0;
		}
		if (targetTs >= segment.get(segment.size() - 1).getTimestamp())
		{
			return segment.size() - 1;
		}

		int lo = 0;
		int hi = segment.size() - 1;
		while (lo < hi)
		{
			int mid = (lo + hi) / 2;
			if (segment.get(mid).getTimestamp() < targetTs)
			{
				lo = mid + 1;
			}
			else
			{
				hi = mid;
			}
		}
		return lo - 1;
	}

	private static WorldPoint interpolate(List<TimelinePoint> segment, long targetTs)
	{
		if (targetTs <= segment.get(0).getTimestamp())
		{
			return worldPointOf(segment.get(0));
		}
		if (targetTs >= segment.get(segment.size() - 1).getTimestamp())
		{
			return worldPointOf(segment.get(segment.size() - 1));
		}

		int idx = bracketBefore(segment, targetTs);
		TimelinePoint a = segment.get(idx);
		TimelinePoint b = segment.get(idx + 1);
		double frac = (double) (targetTs - a.getTimestamp()) / (b.getTimestamp() - a.getTimestamp());
		int x = (int) Math.round(a.getX() + (b.getX() - a.getX()) * frac);
		int y = (int) Math.round(a.getY() + (b.getY() - a.getY()) * frac);
		return new WorldPoint(x, y, a.getPlane());
	}

	private static WorldPoint worldPointOf(TimelinePoint point)
	{
		return new WorldPoint(point.getX(), point.getY(), point.getPlane());
	}

	private static long clamp(long value, long min, long max)
	{
		return Math.max(min, Math.min(max, value));
	}

	private static final class LoadedTimeline
	{
		final List<List<TimelinePoint>> segments;
		final long[] segmentStartOffsets;
		final long totalDurationMs;

		LoadedTimeline(List<List<TimelinePoint>> segments, long[] segmentStartOffsets, long totalDurationMs)
		{
			this.segments = segments;
			this.segmentStartOffsets = segmentStartOffsets;
			this.totalDurationMs = totalDurationMs;
		}
	}
}

