import net.runelite.client.ui.PluginPanel;

public class TimelinePanel extends PluginPanel
{
	private static final Object ALL_SESSIONS = new Object();
	private static final int SCRUBBER_MAX = 10_000;
	private static final double MIN_SPEED = 0.1;
	private static final double MAX_SPEED = 10_000.0;
	private static final int AUTO_REFRESH_MS = 3000;

	private final TimelineSessionStore store;
	private final TimelinePlaybackController playbackController;
	private final ConfigManager configManager;

	private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();

	private final DefaultListModel<Object> listModel = new DefaultListModel<>();
	private final JList<Object> sessionList = new JList<>(listModel);
	private final JButton deleteButton = new JButton("Delete");
	private final JLabel statusLabel = new JLabel("No session selected");
	private final JButton playPauseButton = new JButton("Play");
	private final JSlider scrubber = new JSlider(0, SCRUBBER_MAX, 0);
	private final JSpinner speedSpinner = new JSpinner(new SpinnerNumberModel(1.0, MIN_SPEED, MAX_SPEED, 0.5));
	private final JCheckBox liveTrackingCheckbox = new JCheckBox("Show live tracking on map");
	private final JCheckBox loopCheckbox = new JCheckBox("Loop");
	private final JCheckBox followPlaybackCheckbox = new JCheckBox("Follow player on playback");
	private final Timer autoRefreshTimer = new Timer(AUTO_REFRESH_MS, e -> refresh());

	private List<TimelineSessionMeta> sessions = new ArrayList<>();
	private boolean updatingScrubber;
	private boolean restoringSelection;

	@Inject
	private TimelinePanel(TimelineSessionStore store, TimelinePlaybackController playbackController, ConfigManager configManager, TimelineConfig config)
	{
		super(false);
		this.store = store;
		this.playbackController = playbackController;
		this.configManager = configManager;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildSessionListPanel(), BorderLayout.CENTER);
		add(buildControlsPanel(), BorderLayout.SOUTH);

		liveTrackingCheckbox.setSelected(config.liveTracking());
		liveTrackingCheckbox.addActionListener(e ->
			configManager.setConfiguration("timeline", "liveTracking", liveTrackingCheckbox.isSelected()));

		followPlaybackCheckbox.setSelected(config.followPlayback());
		playbackController.setFollowPlayback(config.followPlayback());
		followPlaybackCheckbox.addActionListener(e ->
		{
			boolean selected = followPlaybackCheckbox.isSelected();
			playbackController.setFollowPlayback(selected);
			configManager.setConfiguration("timeline", "followPlayback", selected);
		});

		playbackController.addListener(this::onPlaybackChanged);
		onPlaybackChanged();

		refresh();
	}

	public void refresh()
	{
		ioExecutor.execute(() ->
		{
			List<TimelineSessionMeta> loaded = store.loadIndex();
			loaded.sort(Comparator.comparingLong(TimelineSessionMeta::getStartTime).reversed());
			SwingUtilities.invokeLater(() -> applySessions(loaded));
		});
	}

	public void setLiveTrackingSelected(boolean selected)
	{
		liveTrackingCheckbox.setSelected(selected);
	}

	public void setFollowPlaybackSelected(boolean selected)
	{
		followPlaybackCheckbox.setSelected(selected);
		playbackController.setFollowPlayback(selected);
	}

	public void shutDown()
	{
		autoRefreshTimer.stop();
		ioExecutor.shutdownNow();
	}

	@Override
	public void onActivate()
	{
		refresh();
		autoRefreshTimer.start();
	}

	@Override
	public void onDeactivate()
	{
		autoRefreshTimer.stop();
	}

	private JPanel buildSessionListPanel()
	{
		sessionList.setCellRenderer(new SessionCellRenderer());
		sessionList.addListSelectionListener(e ->
		{
			if (e.getValueIsAdjusting() || restoringSelection)
			{
				return;
			}
			onSelectionChanged();
		});
		sessionList.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// JList.locationToIndex() returns the nearest row even when the click lands below
				// the last one (empty space in the scroll area) - only keep the selection change
				// if the click actually landed inside a real cell.
				int index = sessionList.locationToIndex(e.getPoint());
				Rectangle bounds = index >= 0 ? sessionList.getCellBounds(index, index) : null;
				if (bounds == null || !bounds.contains(e.getPoint()))
				{
					sessionList.clearSelection();
				}
			}
		});
		sessionList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		sessionList.setForeground(Color.WHITE);
		sessionList.setSelectionBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
		sessionList.setSelectionForeground(Color.WHITE);
		sessionList.setFont(FontManager.getRunescapeSmallFont());

		JLabel headerLabel = new JLabel("Sessions");
		headerLabel.setFont(FontManager.getRunescapeBoldFont());
		headerLabel.setForeground(Color.WHITE);

		JButton refreshButton = styledButton("Refresh");
		refreshButton.addActionListener(e -> refresh());

		JPanel headerRow = new JPanel(new BorderLayout());
		headerRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		headerRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		headerRow.add(headerLabel, BorderLayout.WEST);
		headerRow.add(refreshButton, BorderLayout.EAST);

		deleteButton.setEnabled(false);
		deleteButton.addActionListener(e -> deleteSelected());
		styleButton(deleteButton);
		JPanel actionsRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 6));
		actionsRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		actionsRow.add(deleteButton);

		JScrollPane scrollPane = new JScrollPane(sessionList);
		scrollPane.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR.darker()));
		scrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JPanel panel = new JPanel(new BorderLayout(0, 0));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.add(headerRow, BorderLayout.NORTH);
		panel.add(scrollPane, BorderLayout.CENTER);
		panel.add(actionsRow, BorderLayout.SOUTH);
		return panel;
	}

	private JPanel buildControlsPanel()
	{
		playPauseButton.setEnabled(false);
		playPauseButton.addActionListener(e ->
		{
			if (playbackController.isPlaying())
			{
				playbackController.pause();
			}
			else
			{
				playbackController.play();
			}
		});
		styleButton(playPauseButton);
		loopCheckbox.addActionListener(e -> playbackController.setLoop(loopCheckbox.isSelected()));
		styleCheckbox(loopCheckbox);
		JPanel playbackRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
		playbackRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		playbackRow.add(playPauseButton);
		playbackRow.add(loopCheckbox);

		speedSpinner.setPreferredSize(new Dimension(60, speedSpinner.getPreferredSize().height));
		speedSpinner.addChangeListener(e -> playbackController.setSpeed((Double) speedSpinner.getValue()));
		String speedRangeText = formatSpeed(MIN_SPEED) + "x-" + formatSpeed(MAX_SPEED) + "x";
		speedSpinner.setToolTipText("Range: " + speedRangeText);
		JLabel speedLabel = new JLabel("Speed (" + speedRangeText + ")");
		speedLabel.setToolTipText("Range: " + speedRangeText);
		speedLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		speedLabel.setFont(FontManager.getRunescapeSmallFont());
		JLabel speedUnitLabel = new JLabel("x");
		speedUnitLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		speedUnitLabel.setFont(FontManager.getRunescapeSmallFont());
		JPanel speedRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
		speedRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		speedRow.add(speedLabel);
		speedRow.add(speedSpinner);
		speedRow.add(speedUnitLabel);

		scrubber.setEnabled(false);
		scrubber.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrubber.setUI(new ScrubberUI(scrubber));
		scrubber.addChangeListener(e ->
		{
			if (updatingScrubber)
			{
				return;
			}
			long total = playbackController.getTotalDurationMs();
			if (total <= 0)
			{
				return;
			}
			playbackController.pauseAndSeekTo(total * scrubber.getValue() / SCRUBBER_MAX);
		});

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());

		styleCheckbox(liveTrackingCheckbox);
		styleCheckbox(followPlaybackCheckbox);

		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		scrubber.setAlignmentX(Component.LEFT_ALIGNMENT);
		playbackRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		speedRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		liveTrackingCheckbox.setAlignmentX(Component.LEFT_ALIGNMENT);
		followPlaybackCheckbox.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(statusLabel);
		panel.add(Box.createVerticalStrut(4));
		panel.add(scrubber);
		panel.add(playbackRow);
		panel.add(speedRow);
		panel.add(followPlaybackCheckbox);
		panel.add(Box.createVerticalStrut(6));
		panel.add(liveTrackingCheckbox);
		return panel;
	}

	private static JButton styledButton(String text)
	{
		JButton button = new JButton(text);
		styleButton(button);
		return button;
	}

	private static void styleButton(JButton button)
	{
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setFocusPainted(false);
		button.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 10));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button.isEnabled())
				{
					button.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
	}

	private static void styleCheckbox(JCheckBox checkbox)
	{
		checkbox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		checkbox.setFont(FontManager.getRunescapeSmallFont());
		checkbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		checkbox.setFocusPainted(false);

		Icon icon = checkboxIcon(checkbox);
		checkbox.setIcon(icon);
		checkbox.setSelectedIcon(icon);
	}

	/**
	 * Draws the checkbox box/checkmark ourselves - the platform look-and-feel's default icon
	 * doesn't have enough contrast against this dark panel to tell checked from unchecked.
	 */
	private static Icon checkboxIcon(JCheckBox checkbox)
	{
		int size = 14;
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				boolean selected = checkbox.isSelected();

				g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
				g2.fillRoundRect(x, y, size, size, 4, 4);

				g2.setColor(selected ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR);
				g2.drawRoundRect(x, y, size - 1, size - 1, 4, 4);

				if (selected)
				{
					g2.setColor(ColorScheme.BRAND_ORANGE);
					g2.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g2.drawLine(x + 3, y + 7, x + 6, y + 10);
					g2.drawLine(x + 6, y + 10, x + 11, y + 4);
				}

				g2.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return size;
			}

			@Override
			public int getIconHeight()
			{
				return size;
			}
		};
	}

	/**
	 * A visible dark-theme track/thumb, and clicking anywhere on the track jumps straight there
	 * (stock BasicSliderUI only pages by one block per click instead of scrubbing to position).
	 */
	private static final class ScrubberUI extends BasicSliderUI
	{
		private static final int TRACK_HEIGHT = 4;

		ScrubberUI(JSlider slider)
		{
			super(slider);
		}

		@Override
		protected void installListeners(JSlider slider)
		{
			super.installListeners(slider);

			// BasicSliderUI's own click-in-track handling only pages by one block, and its
			// alternative click-to-position path relies on Component.getMousePosition(), which is
			// a polled query that unreliably returns null right during a mousePressed event -
			// silently no-oping the jump. Reading the coordinates directly off the MouseEvent
			// instead is always reliable, and doubles as drag-to-scrub support.
			MouseAdapter scrubListener = new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (slider.isEnabled())
					{
						slider.setValue(valueForXPosition(e.getX()));
					}
				}

				@Override
				public void mouseDragged(MouseEvent e)
				{
					if (slider.isEnabled())
					{
						slider.setValue(valueForXPosition(e.getX()));
					}
				}
			};
			slider.addMouseListener(scrubListener);
			slider.addMouseMotionListener(scrubListener);
		}

		@Override
		public void paintTrack(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			Rectangle track = trackRect;
			int y = track.y + track.height / 2 - TRACK_HEIGHT / 2;

			g2.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
			g2.fillRoundRect(track.x, y, track.width, TRACK_HEIGHT, TRACK_HEIGHT, TRACK_HEIGHT);

			int filledWidth = thumbRect.x + thumbRect.width / 2 - track.x;
			g2.setColor(slider.isEnabled() ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR.darker());
			g2.fillRoundRect(track.x, y, Math.max(0, Math.min(filledWidth, track.width)), TRACK_HEIGHT, TRACK_HEIGHT, TRACK_HEIGHT);
			g2.dispose();
		}

		@Override
		public void paintThumb(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(slider.isEnabled() ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR);
			g2.fillOval(thumbRect.x, thumbRect.y, thumbRect.width, thumbRect.height);
			g2.dispose();
		}

		@Override
		public void paintFocus(Graphics g)
		{
			// No focus ring - keep the scrubber visually clean.
		}
	}

	private void applySessions(List<TimelineSessionMeta> loaded)
	{
		List<Object> previousSelection = sessionList.getSelectedValuesList();
		boolean previousWasAll = previousSelection.contains(ALL_SESSIONS);
		Set<String> previousIds = previousSelection.stream()
			.filter(TimelineSessionMeta.class::isInstance)
			.map(value -> ((TimelineSessionMeta) value).getId())
			.collect(Collectors.toCollection(HashSet::new));

		this.sessions = loaded;
		listModel.clear();
		if (!loaded.isEmpty())
		{
			listModel.addElement(ALL_SESSIONS);
		}
		for (TimelineSessionMeta meta : loaded)
		{
			listModel.addElement(meta);
		}

		// Restore whatever was selected before this rebuild (e.g. from a periodic auto-refresh)
		// without re-triggering playback loading for the same underlying selection - that would
		// reset an in-progress playback position every few seconds.
		if (previousWasAll)
		{
			restoringSelection = true;
			sessionList.setSelectedValue(ALL_SESSIONS, false);
			restoringSelection = false;
			statusLabel.setText("All sessions (" + sessions.size() + ")");
			return;
		}

		if (!previousIds.isEmpty())
		{
			List<Integer> indices = new ArrayList<>();
			for (int i = 0; i < listModel.size(); i++)
			{
				Object element = listModel.get(i);
				if (element instanceof TimelineSessionMeta && previousIds.contains(((TimelineSessionMeta) element).getId()))
				{
					indices.add(i);
				}
			}

			if (!indices.isEmpty())
			{
				restoringSelection = true;
				sessionList.setSelectedIndices(indices.stream().mapToInt(Integer::intValue).toArray());
				restoringSelection = false;

				if (indices.size() == 1)
				{
					statusLabel.setText(formatLabel((TimelineSessionMeta) listModel.get(indices.get(0))));
				}
				else
				{
					statusLabel.setText(indices.size() + " sessions selected");
				}
				return;
			}
		}

		onSelectionChanged();
	}

	private void onSelectionChanged()
	{
		List<Object> selected = sessionList.getSelectedValuesList();

		if (selected.isEmpty())
		{
			statusLabel.setText("No session selected");
			deleteButton.setEnabled(false);
			return;
		}

		if (selected.contains(ALL_SESSIONS))
		{
			playbackController.loadAllSessions(sessions, false);
			statusLabel.setText("All sessions (" + sessions.size() + ")");
			deleteButton.setEnabled(false);
			return;
		}

		List<TimelineSessionMeta> metas = selected.stream()
			.filter(TimelineSessionMeta.class::isInstance)
			.map(TimelineSessionMeta.class::cast)
			.collect(Collectors.toList());

		deleteButton.setEnabled(!metas.isEmpty());

		if (metas.size() == 1)
		{
			playbackController.loadSession(metas.get(0));
			statusLabel.setText(formatLabel(metas.get(0)));
		}
		else
		{
			// Shift/ctrl-selecting several sessions plays them back to back, same as "All Sessions"
			// but limited to the chosen subset.
			playbackController.loadAllSessions(metas);
			statusLabel.setText(metas.size() + " sessions selected");
		}
	}

	private void deleteSelected()
	{
		List<String> ids = new ArrayList<>();
		for (Object value : sessionList.getSelectedValuesList())
		{
			if (value instanceof TimelineSessionMeta)
			{
				ids.add(((TimelineSessionMeta) value).getId());
			}
		}

		if (ids.isEmpty())
		{
			return;
		}

		String message = ids.size() == 1
			? "Delete this recorded session? This cannot be undone."
			: "Delete these " + ids.size() + " recorded sessions? This cannot be undone.";
		int choice = JOptionPane.showConfirmDialog(this, message, "Delete session" + (ids.size() == 1 ? "" : "s"),
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		deleteButton.setEnabled(false);
		ioExecutor.execute(() ->
		{
			for (String id : ids)
			{
				store.deleteSession(id);
			}
			List<TimelineSessionMeta> loaded = store.loadIndex();
			loaded.sort(Comparator.comparingLong(TimelineSessionMeta::getStartTime).reversed());
			SwingUtilities.invokeLater(() -> applySessions(loaded));
		});
	}

	private void onPlaybackChanged()
	{
		playPauseButton.setText(playbackController.isPlaying() ? "Pause" : "Play");
		long total = playbackController.getTotalDurationMs();
		playPauseButton.setEnabled(total > 0);
		scrubber.setEnabled(total > 0);

		updatingScrubber = true;
		scrubber.setValue(total > 0 ? (int) (playbackController.getCurrentTimeMs() * SCRUBBER_MAX / total) : 0);
		updatingScrubber = false;
	}

	private static String formatLabel(TimelineSessionMeta meta)
	{
		return formatDate(meta.getStartTime()) + " (" + formatDuration(meta.getEndTime() - meta.getStartTime()) + ", " + meta.getPointCount() + " pts)";
	}

	private static String formatDate(long epochMs)
	{
		return new SimpleDateFormat("MMM d, yyyy h:mm a").format(new Date(epochMs));
	}

	private static String formatDuration(long ms)
	{
		long totalSeconds = ms / 1000;
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;
		return hours > 0 ? String.format("%dh %02dm", hours, minutes) : String.format("%dm %02ds", minutes, seconds);
	}

	private static String formatSpeed(double value)
	{
		return value == Math.floor(value) ? String.valueOf((long) value) : String.valueOf(value);
	}

	private final class SessionCellRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			label.setPreferredSize(new Dimension(0, 36));
			label.setFont(FontManager.getRunescapeSmallFont());
			label.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
			label.setBackground(isSelected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			label.setForeground(Color.WHITE);
			if (value == ALL_SESSIONS)
			{
				label.setText("<html><b>All sessions</b> (" + sessions.size() + ")</html>");
			}
			else if (value instanceof TimelineSessionMeta)
			{
				TimelineSessionMeta meta = (TimelineSessionMeta) value;
				label.setText("<html>" + formatDate(meta.getStartTime()) + "<br/><font color='#"
					+ Integer.toHexString(ColorScheme.LIGHT_GRAY_COLOR.getRGB() & 0xFFFFFF) + "'>"
					+ formatDuration(meta.getEndTime() - meta.getStartTime()) + " &middot; " + meta.getPointCount() + " pts</font></html>");
			}
			return label;
		}
	}
}

package com.timeline;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("timeline")
public interface TimelineConfig extends Config
{
	@Range(min = 1, max = 300)
	@ConfigItem(
		keyName = "recordIntervalSeconds",
		name = "Record interval (seconds)",
		description = "How often your location is recorded while logged in",
		position = 0
	)
	default int recordIntervalSeconds()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "pathColor",
		name = "Path color",
		description = "The color used to draw the recorded path on the world map",
		position = 1
	)
	default Color pathColor()
	{
		return new Color(255, 215, 0);
	}

	@ConfigItem(
		keyName = "teleportColor",
		name = "Teleport color",
		description = "The color used for jumps in the path too large to be normal movement (teleports, fairy rings, etc)",
		position = 2
	)
	default Color teleportColor()
	{
		return new Color(220, 20, 20);
	}

	@ConfigItem(
		keyName = "liveTracking",
		name = "Show live tracking",
		description = "Draws the current, in-progress session's path on the world map in real time",
		position = 3
	)
	default boolean liveTracking()
	{
		return false;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "lineThickness",
		name = "Line thickness",
		description = "How thick the recorded path line is drawn on the world map",
		position = 4
	)
	default int lineThickness()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "followPlayback",
		name = "Follow player on playback",
		description = "Keeps the world map centered on the animated marker while a recorded session plays back",
		position = 5
	)
	default boolean followPlayback()
	{
		return false;
	}
}

package com.timeline.data;

import lombok.Value;

@Value
public class TimelinePoint
{
	long timestamp;
	int x;
	int y;
	int plane;
	/**
	 * Whether this point was reached by teleporting from the previous recorded point, detected by
	 * the recorder from the player's actual per-tick position rather than inferred afterwards.
	 */
	boolean teleport;
}

package com.timeline.data;

import lombok.AllArgsConstructor;
import lombok.Data;

@Data
@AllArgsConstructor
public class TimelineSessionMeta
{
	String id;
	long startTime;
	long endTime;
	int pointCount;
}

package com.timeline.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Owns the on-disk layout for recorded timelines under {@code RUNELITE_DIR/timeline/}.
 * All methods here perform blocking file IO and must only be called from a background thread.
 */
@Slf4j
@Singleton
public class TimelineSessionStore
{
	private final Gson gson;

	@Inject
	TimelineSessionStore(Gson gson)
	{
		this.gson = gson.newBuilder().create();
	}

	private Path baseDir()
	{
		return RuneLite.RUNELITE_DIR.toPath().resolve("timeline");
	}

	private Path sessionsDir()
	{
		return baseDir().resolve("sessions");
	}

	private Path indexFile()
	{
		return baseDir().resolve("index.json");
	}

	private Path sessionFile(String sessionId)
	{
		return sessionsDir().resolve(sessionId + ".jsonl");
	}

	public List<TimelineSessionMeta> loadIndex()
	{
		Path file = indexFile();
		if (!Files.exists(file))
		{
			return new ArrayList<>();
		}

		try (Reader reader = Files.newBufferedReader(file))
		{
			Type type = new TypeToken<List<TimelineSessionMeta>>()
			{
			}.getType();
			List<TimelineSessionMeta> metas = gson.fromJson(reader, type);
			return metas != null ? metas : new ArrayList<>();
		}
		catch (IOException e)
		{
			log.warn("Failed to load timeline session index", e);
			return new ArrayList<>();
		}
	}

	public void saveIndex(List<TimelineSessionMeta> metas)
	{
		try
		{
			Files.createDirectories(baseDir());
			try (Writer writer = Files.newBufferedWriter(indexFile()))
			{
				gson.toJson(metas, writer);
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to save timeline session index", e);
		}
	}

	/**
	 * Adds or replaces a session's index entry. Called incrementally while a session is still
	 * being recorded (not just once at the end) so the index reflects an in-progress session even
	 * if the client is killed outright with no shutdown hook ever running.
	 */
	public void upsertSessionMeta(TimelineSessionMeta meta)
	{
		List<TimelineSessionMeta> metas = loadIndex();
		metas.removeIf(existing -> existing.getId().equals(meta.getId()));
		metas.add(meta);
		saveIndex(metas);
	}

	public BufferedWriter openWriter(String sessionId) throws IOException
	{
		Files.createDirectories(sessionsDir());
		return Files.newBufferedWriter(sessionFile(sessionId), StandardOpenOption.CREATE, StandardOpenOption.APPEND);
	}

	public String pointToLine(TimelinePoint point)
	{
		return gson.toJson(point);
	}

	public List<TimelinePoint> loadPoints(String sessionId)
	{
		List<TimelinePoint> points = new ArrayList<>();
		Path file = sessionFile(sessionId);
		if (!Files.exists(file))
		{
			return points;
		}

		try (BufferedReader reader = Files.newBufferedReader(file))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty())
				{
					continue;
				}

				TimelinePoint point = gson.fromJson(line, TimelinePoint.class);
				if (point != null)
				{
					points.add(point);
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load timeline session {}", sessionId, e);
		}

		return points;
	}

	public void deleteSession(String sessionId)
	{
		try
		{
			Files.deleteIfExists(sessionFile(sessionId));
		}
		catch (IOException e)
		{
			log.warn("Failed to delete timeline session {}", sessionId, e);
		}

		List<TimelineSessionMeta> metas = loadIndex();
		metas.removeIf(meta -> meta.getId().equals(sessionId));
		saveIndex(metas);
	}
}

package com.timeline.record;

import com.timeline.TimelineConfig;
import com.timeline.data.TimelinePoint;
import com.timeline.data.TimelineSessionMeta;
import com.timeline.data.TimelineSessionStore;
import java.io.BufferedWriter;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Date;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Records the player's location on an interval while logged in, auto-segmented into one
 * session per login. Disk writes happen on a single dedicated background thread so appends
 * stay strictly ordered without needing extra locking.
 */
@Slf4j
@Singleton
public class TimelineRecorder
{
	/**
	 * Running lets a player cover at most 2 tiles in a single game tick. Anything further than
	 * that between consecutive ticks can only be a teleport.
	 */
	private static final int MAX_WALK_TILES_PER_TICK = 3;

	private final Client client;
	private final TimelineConfig config;
	private final TimelineSessionStore store;

	private final List<TimelinePoint> currentSessionPoints = new ArrayList<>();

	private ExecutorService ioExecutor;

	// Only ever touched from ioExecutor's single thread - no synchronization needed.
	private BufferedWriter writer;
	private String openSessionId;

	private String sessionId;
	private long sessionStartTime;
	private int pointCount;
	private int tickCounter;

	private WorldPoint lastTickLocation;
	private long lastTickTimestamp;

	@Inject
	TimelineRecorder(Client client, TimelineConfig config, TimelineSessionStore store)
	{
		this.client = client;
		this.config = config;
		this.store = store;
	}

	public void startUp()
	{
		ioExecutor = Executors.newSingleThreadExecutor();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			startSession();
		}
	}

	public void shutDown()
	{
		// Write the still-active session's index entry synchronously, directly - not via the
		// executor. If the client is exiting entirely (as opposed to just disabling the plugin),
		// there may be no time left for an async finalize task to run before shutdownNow() below
		// discards it, which would silently drop the whole session from the panel even though its
		// point data is already safely on disk. This is small, bounded, local-disk IO (one JSON
		// list read + write), not the kind of unbounded/network work the no-blocking-shutdown rule
		// is meant to guard against.
		if (sessionId != null)
		{
			String id = sessionId;
			long start = sessionStartTime;
			long end = System.currentTimeMillis();
			int count = pointCount;

			sessionId = null;
			currentSessionPoints.clear();

			if (count > 0)
			{
				store.upsertSessionMeta(new TimelineSessionMeta(id, start, end, count));
			}
		}

		// shutdownNow() (never awaitTermination) may discard a handful of not-yet-executed point
		// appends and skip closing the file handle - an accepted tradeoff, since every point is
		// flushed to disk immediately as it's written, so at most the last point or two is lost.
		if (ioExecutor != null)
		{
			ioExecutor.shutdownNow();
			ioExecutor = null;
		}
	}

	public void onGameStateChanged(GameState newState)
	{
		if (newState == GameState.LOGGED_IN)
		{
			if (sessionId == null)
			{
				startSession();
			}
		}
		else if (newState == GameState.LOGIN_SCREEN || newState == GameState.CONNECTION_LOST)
		{
			endSession();
		}
	}

	public void onGameTick()
	{
		if (sessionId == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		WorldPoint location = player.getWorldLocation();
		long now = System.currentTimeMillis();

		boolean teleported = lastTickLocation != null && chebyshevDistance(lastTickLocation, location) > MAX_WALK_TILES_PER_TICK;

		int ticksPerRecord = Math.max(1, Math.round(config.recordIntervalSeconds() / 0.6f));
		tickCounter++;

		if (teleported)
		{
			// Anchor the walked path right up to the jump, then the jump itself, so only the
			// teleport hop - not the normal movement before it - gets flagged.
			recordPoint(lastTickLocation, lastTickTimestamp, false);
			recordPoint(location, now, true);
			tickCounter = 0;
		}
		else if (tickCounter >= ticksPerRecord)
		{
			recordPoint(location, now, false);
			tickCounter = 0;
		}

		lastTickLocation = location;
		lastTickTimestamp = now;
	}

	private void recordPoint(WorldPoint location, long timestamp, boolean teleport)
	{
		TimelinePoint point = new TimelinePoint(timestamp, location.getX(), location.getY(), location.getPlane(), teleport);
		currentSessionPoints.add(point);
		pointCount++;

		String id = sessionId;
		long start = sessionStartTime;
		int count = pointCount;
		String line = store.pointToLine(point);

		ioExecutor.execute(() ->
		{
			appendLine(id, line);
			// Keep the index up to date as we go, not just at session end, so an in-progress
			// session survives the client being killed outright with no shutdown hook at all.
			store.upsertSessionMeta(new TimelineSessionMeta(id, start, timestamp, count));
		});
	}

	private static int chebyshevDistance(WorldPoint a, WorldPoint b)
	{
		return Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY()));
	}

	public List<TimelinePoint> getCurrentSessionPoints()
	{
		return Collections.unmodifiableList(currentSessionPoints);
	}

	private void startSession()
	{
		sessionId = new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date());
		sessionStartTime = System.currentTimeMillis();
		pointCount = 0;
		tickCounter = 0;
		lastTickLocation = null;
		currentSessionPoints.clear();
	}

	private void endSession()
	{
		if (sessionId == null)
		{
			return;
		}

		String id = sessionId;
		long start = sessionStartTime;
		long end = System.currentTimeMillis();
		int count = pointCount;

		sessionId = null;
		currentSessionPoints.clear();

		if (ioExecutor != null)
		{
			ioExecutor.execute(() -> finalizeSession(id, start, end, count));
		}
	}

	private void appendLine(String id, String line)
	{
		try
		{
			if (writer == null || !id.equals(openSessionId))
			{
				closeWriter();
				writer = store.openWriter(id);
				openSessionId = id;
			}

			writer.write(line);
			writer.newLine();
			writer.flush();
		}
		catch (IOException e)
		{
			log.warn("Failed to append timeline point for session {}", id, e);
		}
	}

	private void finalizeSession(String id, long start, long end, int count)
	{
		if (id.equals(openSessionId))
		{
			closeWriter();
		}

		if (count > 0)
		{
			store.upsertSessionMeta(new TimelineSessionMeta(id, start, end, count));
		}
	}

	private void closeWriter()
	{
		if (writer == null)
		{
			return;
		}

		try
		{
			writer.close();
		}
		catch (IOException e)
		{
			log.warn("Failed to close timeline session file for {}", openSessionId, e);
		}

		writer = null;
		openSessionId = null;
	}
}
